begin;
do $$
declare tu uuid:=gen_random_uuid();su uuid:=gen_random_uuid();ou uuid:=gen_random_uuid();tp uuid:=gen_random_uuid();sp uuid:=gen_random_uuid();op uuid:=gen_random_uuid();l uuid:=gen_random_uuid();doc jsonb;w jsonb;r jsonb;f jsonb;b jsonb;bad jsonb;denied boolean;
begin
 insert into auth.users(id) values(tu),(su),(ou);
 insert into public.profiles(id,user_id,role,display_name,username,specialties) values(tp,tu,'professional','Trainer Test','t_'||substr(replace(tp::text,'-',''),1,12),array['Treinador']),(sp,su,'student','Student Test','t_'||substr(replace(sp::text,'-',''),1,12),'{}'),(op,ou,'student','Other','t_'||substr(replace(op::text,'-',''),1,12),'{}');
 insert into fitto_private.links(id,professional_id,student_id,status) values(l,tp,sp,'active');
 doc:='{"title":"Planning","notes":"","starts":"2026-11-01","phases":[{"name":"Base","weeks":2,"kind":"build","notes":""},{"name":"Deload","weeks":1,"kind":"deload","notes":"Review"}],"sessions":[{"name":"A","times_per_week":2,"exercises":[{"name":"Press","sets":1,"reps":"12","rest_seconds":60,"notes":"","progression":{"mode":"load","increment":2.5,"target_reps":12},"weekly_targets":[{"week":2,"load":"22.5 kg","reps":"12"}],"approved_alternatives":[{"name":"Machine press"}]}]}]}';
 perform set_config('request.jwt.claim.sub',tu::text,true);
 w:=public.workout_api('save',tp,l,jsonb_build_object('content',doc));w:=public.workout_api('publish',tp,l,jsonb_build_object('id',w->>'id','version',w->'version'));
 if w->'published'->'phases' is distinct from doc->'phases' then raise exception 'Phases lost';end if;
 b:=public.training_tools_api('block_save',tp,l,jsonb_build_object('content',doc));
 if (public.training_tools_api('read',tp,l)->'blocks'->0->>'id') is distinct from b->>'id' then raise exception 'Block missing';end if;
 bad:=jsonb_set(doc,'{sessions,0,times_per_week}','0');denied:=false;begin perform fitto_private.validate_workout(bad,true);exception when others then denied:=true;end;if not denied then raise exception 'Invalid frequency accepted';end if;
 bad:=jsonb_set(doc,'{sessions,0,exercises,0,weekly_targets,0,week}','0');denied:=false;begin perform fitto_private.validate_workout(bad,true);exception when others then denied:=true;end;if not denied then raise exception 'Invalid week accepted';end if;
 bad:=jsonb_set(doc,'{sessions,0,exercises,0,progression,increment}','0');denied:=false;begin perform fitto_private.validate_workout(bad,true);exception when others then denied:=true;end;if not denied then raise exception 'Invalid progression accepted';end if;
 perform set_config('request.jwt.claim.sub',su::text,true);
 if jsonb_array_length(public.training_tools_api('read',sp,l)->'blocks')<>0 then raise exception 'Student can read private blocks';end if;
 denied:=false;begin perform public.training_tools_api('block_save',sp,l,jsonb_build_object('content',doc));exception when others then denied:=true;end;if not denied then raise exception 'Student saved block';end if;
 r:=public.execution_api('start',sp,l,jsonb_build_object('plan',w->>'id','division',0));
 if r->'snapshot'->'session'->'exercises'->0->'approved_alternatives' is distinct from doc->'sessions'->0->'exercises'->0->'approved_alternatives' then raise exception 'Alternatives snapshot lost';end if;
 f:=jsonb_build_object('execution_id',r->>'id','exercise_index',0,'message','Question','difficulty',7,'discomfort',true,'alternative','Unapproved');
 denied:=false;begin perform public.training_tools_api('feedback_save',sp,l,f);exception when others then denied:=true;end;if not denied then raise exception 'Unauthorized alternative accepted';end if;
 f:=jsonb_set(f,'{alternative}','"Machine press"');perform public.training_tools_api('feedback_save',sp,l,f);
 perform set_config('request.jwt.claim.sub',tu::text,true);
 denied:=false;begin perform public.training_tools_api('feedback_save',tp,l,f);exception when others then denied:=true;end;if not denied then raise exception 'Trainer wrote student feedback';end if;
 perform public.training_tools_api('feedback_review',tp,l,f);
 if (public.training_tools_api('read',tp,l)->'feedback'->0->>'reviewed') is distinct from 'true' then raise exception 'Review failed';end if;
 perform set_config('request.jwt.claim.sub',su::text,true);
 perform public.training_tools_api('feedback_save',sp,l,f);
 if (public.training_tools_api('read',sp,l)->'feedback'->0->>'reviewed') is distinct from 'false' then raise exception 'Changed feedback should reopen review';end if;
 r:=jsonb_set(r,'{progress,0,0}','{"weight":20,"reps":12,"done":true}');r:=public.execution_api('save',sp,l,r);
 bad:=jsonb_set(f,'{alternative}','""');denied:=false;begin perform public.training_tools_api('feedback_save',sp,l,bad);exception when others then denied:=true;end;if not denied then raise exception 'Alternative changed after logging';end if;
 r:=public.execution_api('finish',sp,l,r);perform public.training_tools_api('feedback_save',sp,l,f);
 perform set_config('request.jwt.claim.sub',ou::text,true);
 denied:=false;begin perform public.training_tools_api('read',op,l);exception when others then denied:=true;end;if not denied then raise exception 'Other student read feedback';end if;
 if has_table_privilege('authenticated','fitto_private.exercise_feedback','select') or has_table_privilege('authenticated','fitto_private.training_blocks','select') or has_function_privilege('anon','public.training_tools_api(text,uuid,uuid,jsonb)','execute') then raise exception 'Unexpected direct privileges';end if;
end $$;
rollback;
select 'PASS: planning round-trip, blocks, frequency/progression/week validation, immutable approved alternatives, feedback ownership, locking after logs, review reset and privacy' as result;
